from pathlib import Path
W = Path("/home/jin/wt_v3_20261102"); SP = W / "scripts_project"


def rep(path, pairs):
    f = Path(path); t = f.read_text(encoding="utf-8")
    for a, b in pairs:
        if a not in t:
            raise SystemExit(f"{f.name}: target not found: {a[:90]}")
        t = t.replace(a, b)
    f.write_text(t, encoding="utf-8"); print("patched", f.name, len(pairs))


